#!/usr/bin/env python3
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1];d=json.loads((ROOT/'Build/TypeSafeBenchmark/full-corpus/prompt-tuning/luna/summary.json').read_text());l=d['luna'];g=d['gemini37'];assert l['complete'] and g['complete'] and d['failedBatches']==0
s='# Luna extraction benchmark\n\nGPT-6 Luna with low reasoning effort, evaluated on 44 frozen windows / 1,755 segments. Production routing unchanged.\n\n'
s+=f"Quality measured against {l['clear']} clear independent Astra model-reviewed labels, not human gold. Includes {l['facts']['reference']} positive fact/task labels and {l['tasks']['reference']} tasks. Uses earlier evaluation conversations, excludes prompt-development conversations. No Luna prompt tuning or fallback. Same bounded extractive classification prompt and input as saved Gemini 3.7. This does not measure rich production fact synthesis or current Gemini 3.8 quality.\n\n"
s+='| Metric | Luna low | Gemini 3.7 saved baseline |\n|---|---:|---:|\n'
for label,key in [('Facts/tasks','facts'),('Tasks','tasks')]:
 for metric in ['precision','recall','f1']:s+=f"| {label} {metric} | {l[key][metric]:.1%} | {g[key][metric]:.1%} |\n"
s+=f"| Wrong task owner, where both predict a task | {l['wrongOwner']} | {g['wrongOwner']} |\n"
for label,key,fmt in [('Estimated USD','estimatedUSD','.4f'),('Median window milliseconds','medianMS','.0f'),('Input tokens','inputTokens',',d'),('Billed output tokens, including reasoning','billedOutputTokens',',d')]:s+=f"| {label} | {format(d['lunaUsage'][key],fmt)} | {format(d['geminiUsage'][key],fmt)} |\n"
s+='\nLuna was called live through the existing Pidgy OpenAI proxy; Gemini uses saved outputs and timings. Latency is not a contemporaneous head-to-head comparison. No benchmark calls were added to Pidgy’s app usage meter. The synthetic connectivity check is stored separately and excluded from the table.\n\nCost estimates use Luna standard short-context $0.10/M input, $0.01/M cached input, $0.50/M output, and Gemini $0.75/M input / $3.75/M output. Output is max(completion_tokens, total_tokens minus prompt_tokens), counting Gemini’s separately reported reasoning tokens once. This corrects the older benchmark estimator which omitted those Gemini reasoning tokens; old totals should not be compared directly with this table. These are estimates, not invoices.\n\nOfficial Luna pricing and capabilities: https://developers.openai.com/api/docs/models/gpt-6-luna\n\nRunner: `tools/luna_extraction_eval.py --live`; omit --live to rescore without API calls. Report: `tools/report_luna_extraction_eval.py`. Private inputs remain in the existing snapshot; outputs, manifest and smoke test are in ignored `Build/TypeSafeBenchmark/full-corpus/prompt-tuning/luna/`. Successful windows resume without being repeated.\n'
(ROOT/'docs/luna-extraction-evaluation.md').write_text(s)
print(s)
